head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(e) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80203.MxDataSet_OnLoadCompleted" });
    }
};

scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80203.btn_cal_onclick" });
    }
};

scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.Text !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("접수일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80203.btn_sys_search_onclick" });
    }
};

scwin.btn_toExcel_onclick = function(e) {
    try {
        MxGrid_1.GridToExcel("금감원송수신로그", "", "8");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80203.btn_toExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

};

scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/sndrcvlog.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn3); // 구 콜백 연결

    scwin.code1Sync();
    // PanelToGroupBox_02(panel_2);

    toDaySet(txb_date);
};
